/*
Package wire holds every request, response and event payload of the local
API as plain Go structs with explicit json tags, plus the scalar types that
keep the Go and TypeScript sides of the wire in agreement. It imports no
other product package, so the TypeScript generator can run without any
embedded asset being built.
*/

/**
 * APIVersion increases on any breaking wire change.
 */
export const APIVersion = 1;
/**
 * ErrorCode is the closed set of error codes of the response envelope.
 */
export type ErrorCode = string;
export const CodeBadRequest: ErrorCode = "bad_request";
export const CodeUnauthenticated: ErrorCode = "unauthenticated";
export const CodeForbidden: ErrorCode = "forbidden";
export const CodeNotFound: ErrorCode = "not_found";
export const CodeMethodNotAllowed: ErrorCode = "method_not_allowed";
export const CodeConflict: ErrorCode = "conflict";
export const CodeRevisionConflict: ErrorCode = "revision_conflict";
export const CodePayloadTooLarge: ErrorCode = "payload_too_large";
export const CodeUnsupportedMediaType: ErrorCode = "unsupported_media_type";
export const CodeValidationFailed: ErrorCode = "validation_failed";
export const CodeConfigInvalid: ErrorCode = "config_invalid";
export const CodeRateLimited: ErrorCode = "rate_limited";
export const CodeInternal: ErrorCode = "internal";
export const CodeUnavailable: ErrorCode = "unavailable";
/**
 * ReasonServerStarting is the reason of the unavailable error every route
 * answers until the database is ready.
 */
export const ReasonServerStarting = "server-starting";
export type ErrorCodeName = typeof CodeBadRequest | typeof CodeUnauthenticated | typeof CodeForbidden | typeof CodeNotFound | typeof CodeMethodNotAllowed | typeof CodeConflict | typeof CodeRevisionConflict | typeof CodePayloadTooLarge | typeof CodeUnsupportedMediaType | typeof CodeValidationFailed | typeof CodeConfigInvalid | typeof CodeRateLimited | typeof CodeInternal | typeof CodeUnavailable;

